-- ============================================================================
-- 10. 동아리 (연합동아리 + 수원대 교내 중앙동아리)
-- ① 연합동아리 43개: 사람이 캠퍼스픽 화면을 직접 보고 고른 동아리의 사실 정보(이름, 분야, 모집 마감일)만.
--    설명은 우리가 새로 쓴 문장, 캠퍼스픽 글·이미지는 복사하지 않음. 마감일 = 본 날(2026-11-12) + D-day
-- ② IT·커리어 연합동아리 13개: 공식 홈페이지 확인. 모집 시기가 정해져 있지 않아 마감일 없음(상시 노출).
-- ③ 수원대 중앙동아리 30개: 제40대 청천 동아리연합회 '중앙동아리 한눈에 보기'.
--    링크는 동아리연합회 공식 인스타그램(개별 동아리 계정은 확인되면 채우기).
-- 다시 실행해도 중복되지 않아요 (source, source_id 기준 덮어쓰기).
-- ============================================================================

alter table explore_postings add column if not exists category text;  -- 동아리 분야 (학술·교양, 체육 ...)

on conflict (source, source_id) do update set
  title = excluded.title, description = excluded.description, deadline = excluded.deadline,
  organization = excluded.organization, category = excluded.category, job_tags = excluded.job_tags,
  url = excluded.url, type = excluded.type, tag = excluded.tag, target = excluded.target;
